data.script:
function normalizeText(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}
function titleCase(value) {
  return String(value || "")
    .replace(/[_-]+/g, " ")
    .split(" ")
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(" ");
}
function departmentLabel(value) {
  const raw = String(value || "").trim();
  if (!raw) return "Department";
  if (raw.toLowerCase() === "ent") return "ENT";
  return titleCase(raw);
}
function consultationLabel(value) {
  const raw = String(value || "").trim().toLowerCase();
  if (raw === "online") return "Online consultation";
  if (raw === "in_person") return "Hospital visit";
  return titleCase(raw);
}

const rows = Array.isArray(vars.reschedule_future_appointments_result?.data) ? vars.reschedule_future_appointments_result.data : [];
function currentParts() {
  return new Intl.DateTimeFormat("en-GB", {
    timeZone: "Asia/Kolkata",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false
  }).formatToParts(new Date()).reduce((acc, part) => {
    acc[part.type] = part.value;
    return acc;
  }, {});
}
function dateOnly(value) {
  const raw = String(value || "").trim();
  const iso = raw.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (iso) return iso[1] + "-" + iso[2] + "-" + iso[3];
  const dmy = raw.match(/^(\d{2})[-/](\d{2})[-/](\d{4})/);
  if (dmy) return dmy[3] + "-" + dmy[2] + "-" + dmy[1];
  return raw.slice(0, 10);
}
function toMinutes(value) {
  const raw = String(value || "").trim();
  const hhmm = raw.match(/([01]?\d|2[0-3]):([0-5]\d)/);
  if (hhmm) return Number(hhmm[1]) * 60 + Number(hhmm[2]);
  const meridian = raw.match(/(\d{1,2}):(\d{2})\s*(AM|PM)/i);
  if (!meridian) return null;
  let hour = Number(meridian[1]);
  const minute = Number(meridian[2]);
  const suffix = meridian[3].toUpperCase();
  if (suffix === "PM" && hour < 12) hour += 12;
  if (suffix === "AM" && hour === 12) hour = 0;
  return hour * 60 + minute;
}
function paymentLabel(value) {
  const raw = String(value || "").trim();
  const map = { paid: "Paid", pending: "Pending", pay_at_hospital: "Pay at hospital", failed: "Payment failed", manual_verify: "Verification pending" };
  return map[raw] || titleCase(raw);
}
function appointmentLine(item, withStatus) {
  const doctor = item.doctor_name || titleCase(item.doctor_id || "doctor");
  const department = departmentLabel(item.department || "");
  const branch = item.branch_name || titleCase(item.branch_id || "");
  const mode = item.consultation_type_label || consultationLabel(item.consultation_type || item.consultation_mode || "");
  const when = dateOnly(item.appointment_date || item.date) + " at " + (item.slot_label || item.appointment_time || item.start_time || "");
  const base = doctor + " | " + department + " | " + branch + " | " + mode + " | " + when;
  if (!withStatus) return base;
  return base + " | Appointment: " + String(item.status || "Status not available") + " | Payment: " + paymentLabel(item.payment_status || "");
}
const parts = currentParts();
const nowDate = parts.year + "-" + parts.month + "-" + parts.day;
const nowMinutes = Number(parts.hour) * 60 + Number(parts.minute);
const future = rows.filter((item) => {
  const date = dateOnly(item.appointment_date || item.date);
  if (!date) return false;
  if (String(item.status || "").toLowerCase() !== "confirmed") return false;
  if (date > nowDate) return true;
  if (date < nowDate) return false;
  const minutes = toMinutes(item.appointment_time || item.slot_label || item.start_time || "");
  return minutes != null && minutes > nowMinutes;
}).sort((a, b) => (String(a.appointment_date || "").localeCompare(String(b.appointment_date || "")) || String(a.appointment_time || a.slot_label || "").localeCompare(String(b.appointment_time || b.slot_label || ""))));
vars.reschedule_future_appointment_route = future.length === 0 ? "none" : future.length === 1 ? "single" : "multiple";
vars.reschedule_future_appointment_options_text = future.map((item, index) => String(index + 1) + ". " + appointmentLine(item, false)).join("\n");
const first = future[0] || {};
vars.reschedule_future_appointments = future;
vars.reschedule_future_appointment_count = future.length;
vars.reschedule_original_appointment_id = first.appointment_id || "";
vars.reschedule_original_patient_id = first.patient_id || ("PAT-" + String(vars.patient_mobile || ""));
vars.reschedule_original_slot_id = first.slot_id || "";
vars.reschedule_original_slot_hold_id = first.slot_hold_id || "";
vars.reschedule_original_slot_label = first.slot_label || "";
vars.reschedule_original_doctor_id = first.doctor_id || "";
vars.reschedule_original_doctor_name = first.doctor_name || titleCase(first.doctor_id || "doctor");
vars.reschedule_original_branch_id = first.branch_id || "";
vars.reschedule_original_branch_name = first.branch_name || titleCase(first.branch_id || "");
vars.reschedule_original_department = first.department || "";
vars.reschedule_original_department_name = departmentLabel(first.department || "");
vars.reschedule_original_consultation_type = first.consultation_type || "";
vars.reschedule_original_consultation_type_label = first.consultation_type_label || consultationLabel(first.consultation_type || "");
vars.reschedule_original_appointment_date = dateOnly(first.appointment_date || first.date) || "";
vars.reschedule_original_appointment_time = first.appointment_time || "";
vars.reschedule_original_payment_status = first.payment_status || "manual_verify";
vars.reschedule_original_reservation_id = first.reservation_id || "";
vars.reschedule_original_reservation_key = first.reservation_key || ((String(first.doctor_id || "").toLowerCase()) + "|" + (dateOnly(first.appointment_date || first.date) || "") + "|" + String(first.appointment_time || "").slice(0, 5));
return { route: vars.reschedule_future_appointment_route, count: future.length };

